import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over' | 'completed';

interface Project {
  id: string;
  name: string;
  quotaPercent: number;
  status: ProjectStatus;
}

const STATUS_META: Record<
  ProjectStatus,
  { label: string; tone: 'success' | 'warning' | 'danger' | 'info' }
> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'На паузе', tone: 'warning' },
  over: { label: 'Превышена квота', tone: 'danger' },
  completed: { label: 'Завершён', tone: 'info' },
};

const ALL_STATUSES = Object.keys(STATUS_META) as ProjectStatus[];

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Редизайн лендинга', quotaPercent: 42, status: 'active' },
  { id: 'p2', name: 'Миграция на новую CRM', quotaPercent: 88, status: 'active' },
  { id: 'p3', name: 'Аудит безопасности', quotaPercent: 100, status: 'over' },
  { id: 'p4', name: 'Мобильное приложение', quotaPercent: 15, status: 'paused' },
  { id: 'p5', name: 'Интеграция с платёжным шлюзом', quotaPercent: 67, status: 'active' },
  { id: 'p6', name: 'Обновление документации', quotaPercent: 100, status: 'completed' },
  { id: 'p7', name: 'Аналитическая панель', quotaPercent: 53, status: 'active' },
  { id: 'p8', name: 'Тестовое покрытие API', quotaPercent: 30, status: 'paused' },
  { id: 'p9', name: 'Отчёт по расходам Q3', quotaPercent: 100, status: 'over' },
  { id: 'p10', name: 'Обучающий курс для команды', quotaPercent: 100, status: 'completed' },
  { id: 'p11', name: 'Оптимизация базы данных', quotaPercent: 74, status: 'active' },
  { id: 'p12', name: 'Внедрение SSO', quotaPercent: 8, status: 'paused' },
];

const PAGE_SIZE = 5;

export default function ProjectSpendPanel() {
  const [activeStatuses, setActiveStatuses] = useState<Set<ProjectStatus>>(
    new Set(ALL_STATUSES)
  );
  const [page, setPage] = useState(1);

  const filteredProjects = useMemo(
    () => PROJECTS.filter((project) => activeStatuses.has(project.status)),
    [activeStatuses]
  );

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const visibleProjects = filteredProjects.slice(
    (page - 1) * PAGE_SIZE,
    page * PAGE_SIZE
  );

  const removeStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) => {
      const next = new Set(prev);
      next.delete(status);
      return next;
    });
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(new Set(ALL_STATUSES));
    setPage(1);
  };

  return (
    <section style={{ display: 'flex', flexDirection: 'column', gap: 16, maxWidth: 560 }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
        {ALL_STATUSES.filter((status) => activeStatuses.has(status)).map((status) => (
          <JxChip
            key={status}
            active
            removable
            onRemove={() => removeStatus(status)}
          >
            {STATUS_META[status].label}
          </JxChip>
        ))}
      </div>

      {filteredProjects.length === 0 ? (
        <JxEmptyState
          title="Нет проектов по выбранным фильтрам"
          message="Все статусы отключены или ни один проект им не соответствует."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
            {visibleProjects.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 16,
                  padding: '8px 0',
                  borderBottom: '1px solid var(--jx-border)',
                }}
              >
                <span style={{ flex: 1, color: 'var(--jx-text)' }}>{project.name}</span>
                <JxProgressCircle value={project.quotaPercent} showValue />
                <JxBadge tone={STATUS_META[project.status].tone}>
                  {STATUS_META[project.status].label}
                </JxBadge>
              </div>
            ))}
          </div>
          <JxPagination total={pageCount} page={page} onPageChange={setPage} />
        </>
      )}
    </section>
  );
}

